#include "visualization_widget.h"
#include <QPainter>
#include <algorithm>
#include <cmath>
VisualizationWidget::VisualizationWidget(QWidget*p):QWidget(p){setMinimumSize(850,470);}
void VisualizationWidget::setResult(const heartgcn::Experiment&e,const heartgcn::Reconstruction&r){exp_=e;rec_=r;ready_=true;update();}
static QColor color(double v,double hi){double t=hi>0?std::clamp(v/hi,0.,1.):0;return QColor::fromRgbF(t,.25+.65*(1-std::abs(2*t-1)),1-t);}
void VisualizationWidget::paintEvent(QPaintEvent*){QPainter p(this);p.fillRect(rect(),Qt::white);p.setPen(Qt::black);if(!ready_){p.drawText(rect(),Qt::AlignCenter,"Press Run to generate synthetic data");return;}int gap=18,top=35,w=(width()-4*gap)/3,h=std::min(250,height()-180),cw=w/exp_.nx,ch=h/exp_.ny;double hi=*std::max_element(exp_.truth.begin(),exp_.truth.end()),eh=0;for(size_t i=0;i<rec_.estimate.size();++i)eh=std::max(eh,std::abs(rec_.estimate[i]-exp_.truth[i]));QString labels[]={"Synthetic truth","Harmonic reconstruction","Absolute error"};for(int k=0;k<3;++k){int ox=gap+k*(w+gap);p.drawText(QRect(ox,5,w,25),Qt::AlignCenter,labels[k]);for(int y=0;y<exp_.ny;++y)for(int x=0;x<exp_.nx;++x){int i=y*exp_.nx+x;double v=k==0?exp_.truth[i]:k==1?rec_.estimate[i]:std::abs(rec_.estimate[i]-exp_.truth[i]);p.fillRect(ox+x*cw,top+y*ch,cw+1,ch+1,color(v,k==2?eh:hi));}p.drawText(ox,top+h+18,QString("blue 0  →  red %1").arg(k==2?eh:hi,0,'g',3));}
 int py=top+h+48,ph=height()-py-28,left=60,right=width()-25;p.drawText(5,py+ph/2,"MAE");p.drawLine(left,py,right,py);p.drawLine(left,py,left,py+ph);double maxMae=0;std::vector<double> fs{.1,.25,.5,.75,1};std::vector<double> ms;for(double f:fs){auto r=heartgcn::sparseReconstruction(exp_,f,rec_.noise);ms.push_back(r.mae);maxMae=std::max(maxMae,r.mae);}QPoint prev;for(size_t i=0;i<fs.size();++i){QPoint pt(left+(right-left)*fs[i],py+ph-(maxMae?ph*ms[i]/maxMae:0));if(i)p.drawLine(prev,pt);p.setBrush(Qt::darkRed);p.drawEllipse(pt,3,3);prev=pt;}p.drawText(QRect(left,py+ph,right-left,25),Qt::AlignCenter,"Sampling fraction  (curve uses selected noise)");}
